import React, { useState, useEffect } from 'react';
import { Plus, Calculator, BookOpen, MapPin, Star, Search, Filter } from 'lucide-react';
import './Timetable.css';

const Timetable = ({ user }) => {
  const [timetable, setTimetable] = useState({});
  const [selectedCell, setSelectedCell] = useState(null);
  const [showAddClass, setShowAddClass] = useState(false);
  const [showGPACalculator, setShowGPACalculator] = useState(false);
  const [currentWeek, setCurrentWeek] = useState(1);
  const [weeklyMemo, setWeeklyMemo] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [popularClasses, setPopularClasses] = useState([]);
  const [draggedClass, setDraggedClass] = useState(null);
  const [touchStart, setTouchStart] = useState(null);
  const [touchEnd, setTouchEnd] = useState(null);

  const timeSlots = [
    '09:00-10:30',
    '10:40-12:10',
    '13:00-14:30',
    '14:40-16:10',
    '16:20-17:50',
    '18:00-19:30',
    '19:40-21:10'
  ];

  const days = ['月', '火', '水', '木', '金'];
  // const daysFull = ['月曜日', '火曜日', '水曜日', '木曜日', '金曜日']; // Reserved for future use

  useEffect(() => {
    const sampleTimetable = {
      '月-1': {
        subject: '線形代数学',
        room: 'A101',
        professor: '田中教授',
        credits: 2,
        description: '行列と線形変換について学ぶ',
        color: '#4facfe',
        rating: 4.2,
        reviews: 45
      },
      '火-2': {
        subject: 'プログラミング基礎',
        room: 'PC室B',
        professor: '佐藤准教授',
        credits: 3,
        description: 'Python プログラミングの基礎',
        color: '#ff6b6b',
        rating: 4.8,
        reviews: 67
      },
      '水-3': {
        subject: '英語コミュニケーション',
        room: 'C205',
        professor: 'Smith先生',
        credits: 2,
        description: '実践的な英語会話',
        color: '#2ecc71',
        rating: 4.5,
        reviews: 32
      },
      '木-1': {
        subject: 'データ構造とアルゴリズム',
        room: 'A203',
        professor: '山田教授',
        credits: 3,
        description: 'コンピュータサイエンスの基礎',
        color: '#f39c12',
        rating: 4.0,
        reviews: 28
      },
      '金-4': {
        subject: '統計学入門',
        room: 'B301',
        professor: '鈴木教授',
        credits: 2,
        description: '統計的思考の基礎',
        color: '#9b59b6',
        rating: 3.8,
        reviews: 41
      }
    };

    const samplePopularClasses = [
      {
        id: 1,
        subject: 'AI・機械学習入門',
        professor: '高橋教授',
        credits: 3,
        rating: 4.9,
        reviews: 89,
        difficulty: '中級',
        description: '人工知能の基礎から応用まで'
      },
      {
        id: 2,
        subject: 'ウェブデザイン',
        professor: '中村准教授',
        credits: 2,
        rating: 4.7,
        reviews: 56,
        difficulty: '初級',
        description: 'HTML/CSS/JavaScriptの実践'
      },
      {
        id: 3,
        subject: '心理学概論',
        professor: '松本教授',
        credits: 2,
        rating: 4.6,
        reviews: 73,
        difficulty: '初級',
        description: '人間の心理と行動について'
      }
    ];

    setTimetable(sampleTimetable);
    setPopularClasses(samplePopularClasses);
  }, []);

  const calculateGPA = () => {
    const classes = Object.values(timetable);
    if (classes.length === 0) return 0;

    let totalPoints = 0;
    let totalCredits = 0;

    classes.forEach(cls => {
      const grade = cls.rating >= 4.5 ? 4.0 : 
                   cls.rating >= 4.0 ? 3.5 :
                   cls.rating >= 3.5 ? 3.0 :
                   cls.rating >= 3.0 ? 2.5 : 2.0;

      totalPoints += grade * cls.credits;
      totalCredits += cls.credits;
    });

    return totalCredits > 0 ? (totalPoints / totalCredits).toFixed(2) : 0;
  };

  const getTotalCredits = () => {
    return Object.values(timetable).reduce((sum, cls) => sum + cls.credits, 0);
  };

  const handleCellClick = (day, timeIndex) => {
    const key = `${day}-${timeIndex}`;
    if (timetable[key]) {
      setSelectedCell({ ...timetable[key], key });
    } else {
      setSelectedCell({ day, timeIndex, key });
      setShowAddClass(true);
    }
  };

  const addClass = (classData) => {
    if (selectedCell) {
      setTimetable({
        ...timetable,
        [selectedCell.key]: classData
      });
      setShowAddClass(false);
      setSelectedCell(null);
    }
  };

  const removeClass = (key) => {
    const newTimetable = { ...timetable };
    delete newTimetable[key];
    setTimetable(newTimetable);
    setSelectedCell(null);
  };

  const TimetableGrid = () => (
    <div className="timetable-grid">
      <div className="time-header"></div>
      {days.map(day => (
        <div key={day} className="day-header">{day}</div>
      ))}

      {timeSlots.map((time, timeIndex) => (
        <React.Fragment key={timeIndex}>
          <div className="time-slot">{time}</div>
          {days.map(day => {
            const key = `${day}-${timeIndex}`;
            const classData = timetable[key];

            return (
              <div
                key={key}
                className={`timetable-cell ${classData ? 'has-class' : 'empty'}`}
                style={classData ? { backgroundColor: classData.color + '20', borderColor: classData.color } : {}}
                onClick={() => handleCellClick(day, timeIndex)}
              >
                {classData && (
                  <div className="class-info">
                    <div className="class-subject">{classData.subject}</div>
                    <div className="class-room">{classData.room}</div>
                    <div className="class-professor">{classData.professor}</div>
                  </div>
                )}
              </div>
            );
          })}
        </React.Fragment>
      ))}
    </div>
  );

  const ClassDetailModal = () => (
    selectedCell && selectedCell.subject && (
      <div className="modal-overlay" onClick={() => setSelectedCell(null)}>
        <div className="modal-content" onClick={e => e.stopPropagation()}>
          <div className="modal-header">
            <h3>{selectedCell.subject}</h3>
            <button className="close-btn" onClick={() => setSelectedCell(null)}>×</button>
          </div>
          <div className="modal-body">
            <div className="class-details">
              <div className="detail-item">
                <MapPin size={16} />
                <span>教室: {selectedCell.room}</span>
              </div>
              <div className="detail-item">
                <BookOpen size={16} />
                <span>担当: {selectedCell.professor}</span>
              </div>
              <div className="detail-item">
                <Star size={16} />
                <span>単位: {selectedCell.credits}</span>
              </div>
              <div className="detail-item">
                <Star size={16} />
                <span>評価: {selectedCell.rating}/5.0 ({selectedCell.reviews}件)</span>
              </div>
            </div>
            <p className="class-description">{selectedCell.description}</p>
            <div className="class-actions">
              <button className="btn btn-secondary" onClick={() => removeClass(selectedCell.key)}>
                削除
              </button>
              <button className="btn btn-primary">掲示板へ</button>
            </div>
          </div>
        </div>
      </div>
    )
  );

  const AddClassModal = () => (
    showAddClass && (
      <div className="modal-overlay" onClick={() => setShowAddClass(false)}>
        <div className="modal-content" onClick={e => e.stopPropagation()}>
          <div className="modal-header">
            <h3>授業を追加</h3>
            <button className="close-btn" onClick={() => setShowAddClass(false)}>×</button>
          </div>
          <div className="modal-body">
            <div className="form-group">
              <label className="form-label">科目名</label>
              <input type="text" className="form-input" placeholder="科目名を入力" />
            </div>
            <div className="form-group">
              <label className="form-label">教室</label>
              <input type="text" className="form-input" placeholder="教室番号" />
            </div>
            <div className="form-group">
              <label className="form-label">担当教授</label>
              <input type="text" className="form-input" placeholder="教授名" />
            </div>
            <div className="form-group">
              <label className="form-label">単位数</label>
              <select className="form-input">
                <option value="1">1単位</option>
                <option value="2">2単位</option>
                <option value="3">3単位</option>
                <option value="4">4単位</option>
              </select>
            </div>
            <div className="form-group">
              <label className="form-label">説明</label>
              <textarea className="form-textarea" placeholder="授業の説明" rows="3" />
            </div>
            <button 
              className="btn btn-primary"
              onClick={() => addClass({
                subject: '新しい授業',
                room: 'A101',
                professor: '教授',
                credits: 2,
                description: '授業の説明',
                color: '#4facfe',
                rating: 4.0,
                reviews: 0
              })}
            >
              追加
            </button>
          </div>
        </div>
      </div>
    )
  );

  const GPACalculatorModal = () => (
    showGPACalculator && (
      <div className="modal-overlay" onClick={() => setShowGPACalculator(false)}>
        <div className="modal-content" onClick={e => e.stopPropagation()}>
          <div className="modal-header">
            <h3>GPA計算機</h3>
            <button className="close-btn" onClick={() => setShowGPACalculator(false)}>×</button>
          </div>
          <div className="modal-body">
            <div className="gpa-summary">
              <div className="gpa-item">
                <span className="gpa-label">現在のGPA</span>
                <span className="gpa-value">{calculateGPA()}</span>
              </div>
              <div className="gpa-item">
                <span className="gpa-label">総単位数</span>
                <span className="gpa-value">{getTotalCredits()}</span>
              </div>
            </div>
            <div className="gpa-classes">
              <h4>登録科目</h4>
              {Object.values(timetable).map((cls, index) => (
                <div key={index} className="gpa-class-item">
                  <span className="class-name">{cls.subject}</span>
                  <span className="class-credits">{cls.credits}単位</span>
                  <span className="class-grade">評価: {cls.rating}/5.0</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    )
  );

  return (
    <div className="timetable">
      <div className="timetable-header">
        <h1 className="page-title">時間割 📅</h1>
        <div className="header-actions">
          <button className="btn btn-outline btn-small" onClick={() => setShowGPACalculator(true)}>
            <Calculator size={16} />
            GPA計算
          </button>
        </div>
      </div>

      <div className="week-selector">
        <div className="week-tabs">
          {[1, 2, 3, 4].map(week => (
            <button
              key={week}
              className={`week-tab ${currentWeek === week ? 'active' : ''}`}
              onClick={() => setCurrentWeek(week)}
            >
              第{week}週
            </button>
          ))}
        </div>
      </div>

      <div className="stats-bar">
        <div className="stat-item">
          <span className="stat-label">GPA</span>
          <span className="stat-value">{calculateGPA()}</span>
        </div>
        <div className="stat-item">
          <span className="stat-label">単位</span>
          <span className="stat-value">{getTotalCredits()}</span>
        </div>
        <div className="stat-item">
          <span className="stat-label">科目数</span>
          <span className="stat-value">{Object.keys(timetable).length}</span>
        </div>
      </div>

      <TimetableGrid />

      <div className="weekly-memo">
        <h3>📝 今週のメモ</h3>
        <textarea
          className="memo-input"
          placeholder="今週の予定やメモを書いてください..."
          value={weeklyMemo}
          onChange={(e) => setWeeklyMemo(e.target.value)}
          rows="3"
        />
      </div>

      <div className="popular-classes">
        <h3>🔥 人気の授業</h3>
        <div className="search-bar">
          <Search size={16} />
          <input 
            type="text"
            className="search-input"
            placeholder="授業を検索..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
          <button className="filter-btn">
            <Filter size={16} />
          </button>
        </div>
        <div className="popular-classes-list">
          {popularClasses.map(cls => (
            <div key={cls.id} className="popular-class-card card">
              <div className="class-header">
                <h4 className="class-title">{cls.subject}</h4>
                <div className="class-rating">
                  <Star size={14} fill="#f39c12" />
                  <span>{cls.rating}</span>
                </div>
              </div>
              <div className="class-meta">
                <span className="professor">{cls.professor}</span>
                <span className="credits">{cls.credits}単位</span>
                <span className={`difficulty difficulty-${cls.difficulty === '初級' ? 'easy' : cls.difficulty === '中級' ? 'medium' : 'hard'}`}>
                  {cls.difficulty}
                </span>
              </div>
              <p className="class-desc">{cls.description}</p>
              <div className="class-actions">
                <button className="btn btn-outline btn-small">詳細</button>
                <button className="btn btn-primary btn-small">追加</button>
              </div>
            </div>
          ))}
        </div>
      </div>

      <button className="fab" onClick={() => setShowAddClass(true)}>
        <Plus size={24} />
      </button>

      <ClassDetailModal />
      <AddClassModal />
      <GPACalculatorModal />
    </div>
  );
};

export default Timetable;
